#!/usr/bin/env python3
"""Source/application integrity of written quartic audit and degree5 extension.
Not a formal proof or independent replay of all geometric arguments.
"""
from pathlib import Path
from itertools import product
import hashlib,json,time,tarfile
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def load(p):return json.loads(p.read_text())
def main():
 start=time.monotonic();assert sha(HERE/'source-v1.html')=='04dfa22c70f97783543eb1a011d90e4d4b9f4fb8f7af394ef6969c1aa491ca29';assert sha(HERE/'source-v1.tar')=='3ecded584936981cf52fa53a4a6fd5c7646729e8b56dd6287b35bd76a05fb9a5';tex=(HERE/'source-keller_map.tex').read_text();assert r'\label{thm:main}' in tex and r'\deg F:=\max_i\deg F_i\le4' in tex
 with tarfile.open(HERE/'source-v1.tar') as archive:assert archive.extractfile('keller_map.tex').read()==(HERE/'source-keller_map.tex').read_bytes()
 receipts={}
 for name,file in [('square-pencils','verify_square_pencils.py'),('structural','verify_structural.py')]:
  p=HERE/(name+'-validation.json');d=load(p);assert d['status']=='pass' and d['source_sha256']==sha(HERE/file) and d['paper_html_sha256']==sha(HERE/'source-v1.html');receipts[name]=dict(receipt_sha256=sha(p),checker_sha256=sha(HERE/file))
  if name=='structural':assert d['helper_sha256']==sha(HERE/'verify_square_pencils.py')
 baseline=ROOT/'jacobian-followup/small-component-gate/classical-validation.json';old=load(baseline);assert old['status']=='pass' and old['excluded_count']==48 and old['remaining_count']==26 and old['source_sha256']==sha(ROOT/'jacobian-followup/small-component-gate/verify_classical.py') and old['proof_sha256']==sha(ROOT/'jacobian-followup/small-component-gate/CLASSICAL_CUBIC_IMPORT.md');profiles=sorted((a,b,c) for a,b,c in product(range(1,8),repeat=3) if a>=b>=c and (a,b,c)<(7,6,4));closed0={tuple(p) for p in old['excluded_profiles']};quartic=[p for p in profiles if p[0]<=4 and p not in closed0];assert quartic==[(4,3,3),(4,4,3),(4,4,4)];closed1=closed0|set(quartic);remaining1=[p for p in profiles if p not in closed1];assert len(closed1)==51 and len(remaining1)==23;extension=[p for p in remaining1 if p[0]<=5 and p[2]<=3];assert extension==[(5,3,3),(5,4,3),(5,5,3)];closed2=closed1|set(extension);remaining2=[p for p in profiles if p not in closed2];assert len(closed2)==54 and len(remaining2)==20;assert all(p[0]>5 or p[2]>=4 for p in remaining2);degree5=[p for p in remaining2 if p[0]==5];assert degree5==[(5,4,4),(5,5,4),(5,5,5)]
 ledger={e['id']:e for e in load(ROOT/'MATH_STATUS.json')['entries']};kp=ledger['KPAIR1'];assert kp['state']=='proved';v=load(ROOT/'jacobian-followup/sparse-eight/coordinate-gates-validation.json');assert v['status']=='pass' and v['plane_degree_import']==100;assert 5*5==25<=100
 result=dict(status='pass',source_sha256=sha(Path(__file__)),quartic_audit_sha256=sha(HERE/'INVERTIBILITY_AUDIT.md'),degree5_extension_sha256=sha(HERE/'EXCEPTIONAL_DEGREE5.md'),paper_html_sha256=sha(HERE/'source-v1.html'),paper_tex_sha256=sha(HERE/'source-keller_map.tex'),paper_archive_sha256=sha(HERE/'source-v1.tar'),exact_identity_replays=receipts,source_sections_reviewed=['2','3'],tameness_section4_audited=False,geometric_and_universal_proofs='Written audit/reproduction; not formalized or independently replayed in full.',external_peer_review_identified=False,baseline_validation_sha256=sha(baseline),quartic_adds=quartic,quartic_excluded_count=51,quartic_remaining=remaining1,quartic_remaining_count=23,degree5_cubic_component_adds=extension,total_excluded=sorted(closed2),total_excluded_count=54,remaining_profiles=remaining2,remaining_count=20,remaining_degree5_profiles=degree5,three_variable_ordinary_degree_interval=[5,7],exceptional_scalar_exclusion_degree=5,cubic_component_completion_inverse_bound=5,extended_plane_fibre_bound=25,degree6_extension_not_proved=True,degree6_UFD_degree_bound_survivors=[[3,1],[3,2],[4,2]],positive_witness_bounds_changed=False,global_simplicity_minima_closed=False,scope='Explicit written quartic invertibility audit plus independently reconstructed selected coefficient/operator identities; separate universal degree5 exceptional-scalar proof and cubic-component extension. Receipt pins applications and trust boundaries, not a formal proof of the imported geometry, Moh or a global optimum.',seconds=round(time.monotonic()-start,3));(HERE/'validation.json').write_text(json.dumps(result,indent=2,sort_keys=True)+'\n');print('PASS quartic+degree5 extension:54 excluded,20 remaining;3D degree[5,7]; no construction change',flush=True)
if __name__=='__main__':main()
